spec.test_code:
#include <cassert>
#include <iostream>
#include "lru.hpp"

int main() {
    LRUCache cache(2);
    cache.put(1, 10);
    cache.put(2, 20);
    assert(cache.get(1) == 10);
    cache.put(3, 30); // evicts 2
    assert(cache.get(2) == -1);
    cache.put(4, 40); // evicts 1
    assert(cache.get(1) == -1);
    assert(cache.get(3) == 30);
    assert(cache.get(4) == 40);
    std::cout << "C++20 LRU Cache passed!\n";
    return 0;
}
